/** Initializes the dashboard widgets. */
function initDashboard(): void {

      Merge them using trailing commas:

const a = 1,
  b = 2,
  c = 3;

      Remove the curly braces:

// Before
if (ready) {
  init();
}

// After
if (ready) init();

      Wrap the entire body in an IIFE with try/catch:

(function erpModuleName() {
  try {
    // …entire body…
  } catch (e) {
    console.error("[erpModuleName]", e);
  }
})();

      For form fields, convert:

// Before
const input = document.querySelector('#myForm input[name="email"]');

// After
const input = document.forms.myForm.elements.namedItem("email");

      Wrap with a dataset guard:

if (!el.dataset.submitBound) {
  el.addEventListener("submit", handler);
  el.dataset.submitBound = "1";
}

      Create a named wrapper function:

export async function tasksGet(): Promise<void> {
  try {
    const res = await axios.get(resolveUrl("/api/tasks"));
    if (!res || res.status !== 200) {
      guard.error("Request failed");
      return;
    }
    // …process res.data…
  } catch (e) {
    console.error("[tasksGet]", e);
  }
}
